import{_ as t,o,c as a,a2 as r}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Bento Grids — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"bento-grids-04-troubleshooting-and-faqs.md","filePath":"bento-grids-04-troubleshooting-and-faqs.md"}'),n={name:"bento-grids-04-troubleshooting-and-faqs.md"};function i(s,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="bento-grids-—-troubleshooting-faqs" tabindex="-1">Bento Grids — Troubleshooting &amp; FAQs <a class="header-anchor" href="#bento-grids-—-troubleshooting-faqs" aria-label="Permalink to &quot;Bento Grids — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common questions and what to do when things don&#39;t work as expected</em></p><hr><h2 id="who-can-create-bento-grids" tabindex="-1">Who can create Bento Grids? <a class="header-anchor" href="#who-can-create-bento-grids" aria-label="Permalink to &quot;Who can create Bento Grids?&quot;">​</a></h2><p>Any workspace member — both Admins and Builders — can create, save, and export Bento Grids.</p><hr><h2 id="does-the-bento-grid-stay-in-sync-with-my-release-notes" tabindex="-1">Does the Bento Grid stay in sync with my Release Notes? <a class="header-anchor" href="#does-the-bento-grid-stay-in-sync-with-my-release-notes" aria-label="Permalink to &quot;Does the Bento Grid stay in sync with my Release Notes?&quot;">​</a></h2><p>No. Once you save a Bento Grid, it is a snapshot of the content at that point. If you update the Release Notes after saving, the grid does not update automatically — you need to regenerate it. Regenerating runs the AI grouping again on the latest content.</p><hr><h2 id="can-i-create-a-bento-grid-without-release-notes" tabindex="-1">Can I create a Bento Grid without Release Notes? <a class="header-anchor" href="#can-i-create-a-bento-grid-without-release-notes" aria-label="Permalink to &quot;Can I create a Bento Grid without Release Notes?&quot;">​</a></h2><p>Yes. The file upload option lets you create a Bento Grid from any content source — a markdown file, a plain text document, or an export from another tool. The result is stored as a standalone grid (not linked to any Release).</p><hr><h2 id="the-ai-grouping-doesn-t-look-right-can-i-fix-it" tabindex="-1">The AI grouping doesn&#39;t look right. Can I fix it? <a class="header-anchor" href="#the-ai-grouping-doesn-t-look-right-can-i-fix-it" aria-label="Permalink to &quot;The AI grouping doesn&#39;t look right. Can I fix it?&quot;">​</a></h2><p>Yes. The review step before the grid renders is your chance to adjust the grouping. You can reorder, merge, or split cells. The AI grouping is a starting point — you are always in control of the final layout.</p><hr><h2 id="can-i-have-more-than-one-bento-grid-per-release-note" tabindex="-1">Can I have more than one Bento Grid per Release Note? <a class="header-anchor" href="#can-i-have-more-than-one-bento-grid-per-release-note" aria-label="Permalink to &quot;Can I have more than one Bento Grid per Release Note?&quot;">​</a></h2><p>Only one saved Bento Grid per Release Note is kept. If you regenerate a grid for the same Release Note, it replaces the previous saved version. To preserve a previous version, export it as PNG or PowerPoint before regenerating.</p><hr><h2 id="how-many-cells-can-a-bento-grid-have" tabindex="-1">How many cells can a Bento Grid have? <a class="header-anchor" href="#how-many-cells-can-a-bento-grid-have" aria-label="Permalink to &quot;How many cells can a Bento Grid have?&quot;">​</a></h2><p>There is a maximum number of sections (cells) per grid. If your source content has too many distinct items, the AI will group related items together to stay within that limit. This is by design — a grid with too many cells becomes hard to read at a glance.</p><hr><h2 id="i-don-t-see-the-google-slides-export-option" tabindex="-1">I don&#39;t see the Google Slides export option. <a class="header-anchor" href="#i-don-t-see-the-google-slides-export-option" aria-label="Permalink to &quot;I don&#39;t see the Google Slides export option.&quot;">​</a></h2><p>Google Slides upload requires a Google account to be connected. If you haven&#39;t connected Google, the option may not appear or will prompt you to authenticate. Contact your workspace admin if you need help with the Google integration.</p><hr><h2 id="my-bento-grid-was-saved-but-i-can-t-find-it" tabindex="-1">My Bento Grid was saved but I can&#39;t find it. <a class="header-anchor" href="#my-bento-grid-was-saved-but-i-can-t-find-it" aria-label="Permalink to &quot;My Bento Grid was saved but I can&#39;t find it.&quot;">​</a></h2><p>Open the Bento Grids module from the left-hand navigation. The list shows:</p><ul><li>All Release Notes for your organization that have a saved grid</li><li>Any standalone (file-sourced) grids</li></ul><p>If a Release Note appears without a &quot;Saved&quot; indicator, a grid has not been saved for it yet. The entry is shown so you can start creating one.</p><hr><h2 id="the-png-export-looks-blurry-or-low-resolution" tabindex="-1">The PNG export looks blurry or low-resolution. <a class="header-anchor" href="#the-png-export-looks-blurry-or-low-resolution" aria-label="Permalink to &quot;The PNG export looks blurry or low-resolution.&quot;">​</a></h2><p>Try exporting in a larger aspect ratio (16:9 is the widest) and ensuring the grid has loaded fully before exporting. If the issue persists, use the PowerPoint export and save the slide as an image from within PowerPoint or Google Slides for higher resolution output.</p><hr><h2 id="can-i-edit-the-grid-cells-manually" tabindex="-1">Can I edit the grid cells manually? <a class="header-anchor" href="#can-i-edit-the-grid-cells-manually" aria-label="Permalink to &quot;Can I edit the grid cells manually?&quot;">​</a></h2><p>The review step lets you adjust the grouping before the grid is rendered. After rendering, the content of cells is not directly editable within Lodestone — if you need to change the text, you can either regenerate from updated source content or edit the exported PowerPoint or Google Slides file directly.</p><hr><h2 id="does-archiving-a-release-affect-its-bento-grids" tabindex="-1">Does archiving a Release affect its Bento Grids? <a class="header-anchor" href="#does-archiving-a-release-affect-its-bento-grids" aria-label="Permalink to &quot;Does archiving a Release affect its Bento Grids?&quot;">​</a></h2><p>No. Archiving a Release does not delete or archive the Bento Grids associated with its Release Notes. Saved grids remain accessible in the Bento Grids module.</p><hr>',38)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
